function fizz(n) {
  return Array.from({length:n},(_,i)=>{
    const x=i+1;
    return x%15===0?'FizzBuzz':x%3===0?'Fizz':
      x%5===0?'Buzz':String(x);
  });
}

static List<String> fizz(int n) {
  List<String> a=new ArrayList<>();
  for(int x=1;x<=n;x++)
    a.add(x%15==0?"FizzBuzz":x%3==0?"Fizz":
          x%5==0?"Buzz":String.valueOf(x));
  return a;
}
